def boxmask(im):
    im=im.astype(int); r,g,b=im[...,0],im[...,1],im[...,2]
    return (b>r+8)&(b>100)&(g>r)
def rep(im):
    red,_=masks(im); bm=boxmask(im); out=[]
    for m in (red,bm):
        ys,xs=np.nonzero(m); out.append((len(xs), round(xs.mean(),1) if len(xs) else None, round(ys.mean(),1) if len(xs) else None, (xs.min(),xs.max(),ys.min(),ys.max()) if len(xs) else None))
    return out
